mapper.sql:
WHERE 
AND action=#{query.action}
AND actor_id=#{query.actorId}
AND category=#{query.category}
AND outcome=#{query.outcome}
AND resource_type=#{query.resourceType}
AND trace_id=#{query.traceId}
AND created_at >= #{query.from}
AND created_at < #{query.to}

mapper.select:
SELECT id FROM nw_audit_logs WHERE  AND created_at < #{cutoff}
ORDER BY EXISTS(SELECT 1 FROM nw_foundation_audit_holds h WHERE h.audit_id=nw_audit_logs.id AND h.released_at IS NULL
  AND (h.expires_at IS NULL OR h.expires_at > now())),created_at,id LIMIT #{limit}

SELECT count(DISTINCT audit_id) FROM nw_foundation_audit_holds WHERE scope=#{scope} AND released_at IS NULL
AND (expires_at IS NULL OR expires_at > now()) AND audit_id IN
#{id}

mapper.delete:
WITH authorized AS MATERIALIZED (SELECT set_config('app.audit_cleanup','on',true))
DELETE FROM nw_audit_logs USING authorized WHERE  AND created_at < #{cutoff}
AND id IN #{id}
AND NOT EXISTS(SELECT 1 FROM nw_foundation_audit_holds h WHERE h.audit_id=nw_audit_logs.id AND h.released_at IS NULL AND (h.expires_at IS NULL OR h.expires_at > now()))
